# Date and time arithmetic (R71): month ends, leap years, INTERVAL in every unit, DATEDIFF / TIMESTAMPDIFF / PERIOD_*, week numbers in every mode, DATE_FORMAT / STR_TO_DATE, TIME sums and
# overflow, dates in WHERE / ORDER BY / GROUP BY and in a column default. A line is a statement, '--' a setup statement run on both.
# (not compared, MySQL quirks or forms RuSQL leaves: a DATE column against '2024-1-31' as a date, DATE_SUB('0001-01-01', INTERVAL 1 DAY) = '0000-00-00', INTERVAL '1.5' DAY as 1 day, INTERVAL 1 DAY + date with the INTERVAL first)
# (not compared, they depend on the time zone of the machine: UNIX_TIMESTAMP / FROM_UNIXTIME; tests/test_r71_transactions.cpp reads FROM_UNIXTIME with a fraction)
--CREATE TABLE dd (id INT PRIMARY KEY, d DATE, t DATETIME, tm TIME, s VARCHAR(20))
--INSERT INTO dd VALUES (1, '2024-01-31', '2024-01-31 23:59:59', '23:59:59', '2024-01-31'), (2, '2024-02-29', '2024-02-29 00:00:00', '00:00:00', '2024-2-29'), (3, '2023-12-31', '2023-12-31 12:30:45', '838:59:59', '20231231'), (4, '2024-03-31', '2024-03-31 01:02:03', '-12:30:00', '31/03/2024'), (5, NULL, NULL, NULL, NULL)
SELECT d, DATE_ADD(d, INTERVAL 1 MONTH), DATE_ADD(d, INTERVAL 13 MONTH), DATE_SUB(d, INTERVAL 1 MONTH), DATE_ADD(d, INTERVAL 1 YEAR), DATE_ADD(d, INTERVAL -1 DAY) FROM dd ORDER BY id
SELECT d, d + INTERVAL 1 DAY, d - INTERVAL 1 WEEK, d + INTERVAL 1 QUARTER, d + INTERVAL '1-2' YEAR_MONTH, d - INTERVAL '2 3' DAY_HOUR FROM dd ORDER BY id
SELECT t, t + INTERVAL 1 SECOND, t + INTERVAL 90 MINUTE, t + INTERVAL 25 HOUR, t + INTERVAL '1:30' HOUR_MINUTE, t - INTERVAL '1 1:1:1' DAY_SECOND, t + INTERVAL 1500000 MICROSECOND FROM dd ORDER BY id
SELECT d, DATEDIFF(d, '2024-01-01'), DATEDIFF('2024-01-01', d), DATEDIFF(t, d), TO_DAYS(d), FROM_DAYS(TO_DAYS(d) + 1) FROM dd ORDER BY id
SELECT t, TIMESTAMPDIFF(DAY, '2024-01-01', t), TIMESTAMPDIFF(MONTH, '2024-01-31', t), TIMESTAMPDIFF(YEAR, '2000-02-29', t), TIMESTAMPDIFF(HOUR, '2024-01-01 12:00:00', t), TIMESTAMPDIFF(WEEK, '2024-01-01', t), TIMESTAMPDIFF(QUARTER, '2023-01-01', t) FROM dd ORDER BY id
SELECT TIMESTAMPDIFF(MONTH, '2024-01-31', '2024-02-29'), TIMESTAMPDIFF(MONTH, '2024-03-31', '2024-02-29'), TIMESTAMPDIFF(YEAR, '2024-02-29', '2025-02-28'), TIMESTAMPDIFF(YEAR, '2024-02-29', '2028-02-29'), TIMESTAMPDIFF(SECOND, '2024-01-01 00:00:00', '2023-12-31 23:59:00'), TIMESTAMPDIFF(MICROSECOND, '2024-01-01 00:00:00', '2024-01-01 00:00:01.5')
SELECT TIMESTAMPADD(MONTH, 1, '2024-01-31'), TIMESTAMPADD(WEEK, 2, '2024-02-29'), TIMESTAMPADD(YEAR, 1, '2024-02-29'), TIMESTAMPADD(MINUTE, 90, '2024-01-01 23:00:00'), TIMESTAMPADD(DAY, -366, '2024-12-31')
SELECT d, LAST_DAY(d), DAY(LAST_DAY(d)), DAYOFYEAR(d), DAYOFWEEK(d), WEEKDAY(d), DAYNAME(d), MONTHNAME(d), QUARTER(d) FROM dd ORDER BY id
SELECT d, WEEK(d), WEEK(d, 1), WEEK(d, 2), WEEK(d, 3), WEEK(d, 4), WEEK(d, 5), WEEK(d, 6), WEEK(d, 7), YEARWEEK(d), YEARWEEK(d, 1), WEEKOFYEAR(d) FROM dd ORDER BY id
SELECT '2021-01-01', WEEK('2021-01-01'), WEEK('2021-01-01', 1), YEARWEEK('2021-01-01'), YEARWEEK('2021-01-01', 1), WEEK('2020-12-31', 3), WEEK('2018-12-31', 3), YEARWEEK('2018-12-31', 3), WEEK('2000-01-01', 0), WEEK('2000-01-01', 2)
SELECT d, DATE_FORMAT(d, '%Y-%m-%d'), DATE_FORMAT(d, '%d/%m/%y'), DATE_FORMAT(d, '%a %b %e %Y'), DATE_FORMAT(d, '%W %M %D'), DATE_FORMAT(d, '%j %U %u %V %v %X %x'), DATE_FORMAT(d, '%c %w %%') FROM dd ORDER BY id
SELECT t, DATE_FORMAT(t, '%H:%i:%s'), DATE_FORMAT(t, '%h:%i %p'), DATE_FORMAT(t, '%I %l %k %S %f'), DATE_FORMAT(t, '%r'), DATE_FORMAT(t, '%T'), DATE_FORMAT(t, '%Y%m%d%H%i%s') FROM dd ORDER BY id
SELECT STR_TO_DATE('31/03/2024', '%d/%m/%Y'), STR_TO_DATE('March 5, 2024', '%M %e, %Y'), STR_TO_DATE('2024-03-05 14:07:09', '%Y-%m-%d %H:%i:%s'), STR_TO_DATE('05-03-24', '%d-%m-%y'), STR_TO_DATE('2024-02-30', '%Y-%m-%d'), STR_TO_DATE('x', '%Y'), STR_TO_DATE('12:30 PM', '%h:%i %p'), STR_TO_DATE('2024 10', '%Y %j')
SELECT s, STR_TO_DATE(s, '%Y-%m-%d'), DATE(s), CAST(s AS DATE), s + INTERVAL 1 DAY FROM dd ORDER BY id
SELECT tm, ADDTIME(tm, '01:00:00'), SUBTIME(tm, '00:00:01'), TIME_TO_SEC(tm), SEC_TO_TIME(TIME_TO_SEC(tm) + 3600), tm + 1, TIMEDIFF(tm, '10:00:00'), HOUR(tm), MINUTE(tm), SECOND(tm) FROM dd ORDER BY id
SELECT TIMEDIFF('2024-01-02 00:00:00', '2024-01-01 12:00:00'), TIMEDIFF('12:00:00', '2024-01-01 12:00:00'), ADDTIME('2024-01-01 23:59:59', '00:00:01'), ADDTIME('23:59:59', '00:00:01'), SUBTIME('00:00:00', '00:00:01'), SEC_TO_TIME(-1), SEC_TO_TIME(3020399), SEC_TO_TIME(3020400), MAKETIME(25, 61, 0), MAKETIME(-1, 5, 6)
SELECT MAKEDATE(2024, 60), MAKEDATE(2024, 366), MAKEDATE(2023, 366), MAKEDATE(2024, 0), PERIOD_ADD(202401, 14), PERIOD_ADD(202412, 1), PERIOD_DIFF(202403, 202312), PERIOD_DIFF(202401, 202401), PERIOD_ADD(9912, 1)
SELECT EXTRACT(YEAR FROM t), EXTRACT(MONTH FROM t), EXTRACT(WEEK FROM t), EXTRACT(QUARTER FROM t), EXTRACT(DAY_HOUR FROM t), EXTRACT(YEAR_MONTH FROM t), EXTRACT(HOUR_SECOND FROM t), EXTRACT(MICROSECOND FROM t) FROM dd ORDER BY id
SELECT d, d < '2024-02-01', d = 20240131, d BETWEEN '2024-01-01' AND '2024-02-29', d IN ('2024-02-29', '2023-12-31'), t >= '2024-01-31', t = d FROM dd ORDER BY id
SELECT id FROM dd WHERE d >= '2024-01-01' AND d < DATE_ADD('2024-01-01', INTERVAL 2 MONTH) ORDER BY id
SELECT id, d FROM dd WHERE YEAR(d) = 2024 AND MONTH(d) IN (1, 3) ORDER BY d DESC
SELECT YEAR(d) AS y, COUNT(*), MIN(d), MAX(d), MAX(t) FROM dd GROUP BY YEAR(d) ORDER BY y
SELECT DATE_FORMAT(d, '%Y-%m') AS m, COUNT(*) FROM dd GROUP BY m ORDER BY m
SELECT d, t FROM dd ORDER BY d DESC, t
SELECT MIN(d), MAX(d), MIN(tm), MAX(tm), MIN(t), MAX(t) FROM dd
SELECT d, COALESCE(d, '1970-01-01'), IFNULL(d, 'none'), d IS NULL, COALESCE(t, d) FROM dd ORDER BY id
SELECT CAST('2024-02-30' AS DATE), CAST('2024-13-01' AS DATE), CAST('0000-00-00' AS DATE), CAST('2024-02-29 25:00:00' AS DATETIME), CAST('24:00:00' AS TIME), CAST(20240229 AS DATE), CAST(240229 AS DATE), CAST('2024-1-1' AS DATE)
SELECT DATE('2024-02-29 13:45:10'), TIME('2024-02-29 13:45:10'), DATE('x'), TIME('x'), DATE(20240229134510), TIMESTAMP('2024-02-29', '13:45:10'), TIMESTAMP('2024-02-29 01:00:00', '25:00:00'), TIMESTAMP('2024-02-29')
SELECT DATE_ADD('2024-02-29', INTERVAL 1 YEAR), DATE_ADD('2023-02-28', INTERVAL 1 YEAR), DATE_ADD('2024-12-31', INTERVAL 1 DAY), DATE_ADD('9999-12-31', INTERVAL 1 DAY), DATE_ADD('2024-01-31', INTERVAL 1 MONTH)
SELECT DATE_ADD('2024-01-01', INTERVAL '1' DAY), DATE_ADD('2024-01-01', INTERVAL 1.5 DAY), DATE_ADD('2024-01-01', INTERVAL NULL DAY), DATE_ADD(NULL, INTERVAL 1 DAY), DATE_ADD('2024-01-01', INTERVAL 'x' DAY)
SELECT '2024-01-31' + INTERVAL 1 MONTH, '2024-01-31 10:00:00' + INTERVAL 1 DAY, 20240131 + INTERVAL 1 DAY, '2024-01-31' - INTERVAL 1 MONTH
SELECT GET_FORMAT(DATE, 'ISO'), GET_FORMAT(DATE, 'USA'), GET_FORMAT(TIME, 'EUR'), GET_FORMAT(DATETIME, 'JIS')
SELECT CURDATE() = CURRENT_DATE(), CURDATE() = DATE(NOW()), NOW() >= '2024-01-01', YEAR(CURDATE()) >= 2024, DATE(NOW()) = CURDATE(), TIMESTAMPDIFF(SECOND, NOW(), NOW()), NOW() - NOW()
SELECT DATEDIFF(NOW(), NOW()), DATEDIFF(CURDATE() + INTERVAL 1 DAY, CURDATE()), CURDATE() + INTERVAL 0 DAY = CURDATE(), SLEEP(0)
SELECT SYSDATE() >= NOW(), UTC_DATE() IS NOT NULL, UTC_TIMESTAMP() IS NOT NULL, CONVERT_TZ('2024-01-01 12:00:00', '+00:00', '+09:00'), CONVERT_TZ('2024-01-01 12:00:00', '+09:00', '-05:00')
--CREATE TABLE dflt (id INT PRIMARY KEY, created DATETIME DEFAULT '2024-01-01 00:00:00', day DATE DEFAULT '2024-02-29', nowish TIMESTAMP DEFAULT CURRENT_TIMESTAMP, upd DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)
INSERT INTO dflt (id) VALUES (1)
SELECT id, created, day, nowish IS NOT NULL, upd IS NOT NULL FROM dflt
UPDATE dflt SET created = '2025-05-05 05:05:05' WHERE id = 1
SELECT id, created, day, TIMESTAMPDIFF(SECOND, upd, NOW()) < 5 FROM dflt
INSERT INTO dflt (id, day) VALUES (2, '2024-02-30')
INSERT INTO dflt (id, day) VALUES (3, '2024-02-30 10:00:00')
INSERT INTO dflt (id, day, created) VALUES (4, '24-12-25', '99-12-31 23:59:59')
INSERT INTO dflt (id, day, created) VALUES (5, '2024/03/05', '2024.03.05 1:2:3')
INSERT INTO dflt (id, day) VALUES (6, 20240305), (7, '20240305'), (8, 240305)
SELECT id, created, day FROM dflt ORDER BY id
